package local.pocketchat;
import android.app.*;import android.content.*;import org.json.*;

final class DeliveryUi {
 static void show(MainActivity a,String id){JSONObject r=a.session.deliveries.get(id);if(r==null)return;boolean uncertain=r.optInt("attempted")!=0&&!r.optString("state").equals("completed");String body=DeliveryStore.label(r.optString("state"))+"\n"+r.optString("detail")+"\n\n"+DraftUi.preview(r.optString("body"));AlertDialog.Builder d=new AlertDialog.Builder(a).setTitle("发送记录").setMessage(body).setNegativeButton("关闭",null);if(uncertain)d.setPositiveButton("继续核对",(x,w)->{if(a.session.pending!=null&&id.equals(a.session.pending.optString("id"))){if(a.session.networkReady&&!a.session.offline)a.session.sync();else a.session.reconnect();}else{a.showPage(true);a.status("请在原网页核对这条消息；不会自动重发");}}).setNeutralButton("查看原网页",(x,w)->a.showPage(true));else d.setPositiveButton("放回输入框",(x,w)->{String current=a.input.getText().toString();if(!DraftArchive.get(a).save(a.conversation,current,"元婴期院士草稿")){a.status("当前草稿保存失败，未替换");return;}a.input.setText(r.optString("body"));a.input.setSelection(a.input.length());if(!r.optString("state").equals("completed"))a.session.deliveries.update(id,"draft","已放回输入框，核对后再发送",false,"","");a.session.changed();a.status(r.optString("files","[]").equals("[]")?"已放回输入框，点发送后才会发送":"已恢复文字，请核对并重新选择附件后发送");});d.show();}
 static void list(MainActivity a){JSONArray records=a.session.deliveries.list(a.conversation);if(records.length()==0){a.status("当前对话还没有本机发送记录");return;}String[] labels=new String[records.length()];for(int i=0;i<labels.length;i++){JSONObject r=records.optJSONObject(records.length()-1-i);labels[i]=DeliveryStore.label(r.optString("state"))+" · "+DraftUi.preview(r.optString("body"));}new AlertDialog.Builder(a).setTitle("发送记录").setItems(labels,(d,n)->show(a,records.optJSONObject(records.length()-1-n).optString("id"))).setNegativeButton("关闭",null).show();}
}
